  u8 = u8_strconv_from_encoding (str, encoding, iconveh_error);
  if (!u8)
    return;

  u32 = u8_to_u32 (u8, strlen ((char *) u8), NULL, &u32len);

  if (u8 && strcmp (str, (char *) u8) != 0)
    for (i = 0; i < strlen ((char *) u8); i++)
      fprintf (stderr, "UTF-8 %s[%lu] = 0x%02x\n",
