    },
    {
      "name": "Punycode 编解码",
      "description": "实现 RFC 3492 Punycode 算法，将 Unicode 字符串编码为 ASCII 兼容的 ACE 前缀域名格式，及反向解码。",
      "evidence": ["lib/punycode.c", "lib/idn2.h.in:309"]
    },
    {
      "name": "Unicode TR46 兼容处理",
      "description": "实现 Unicode IDNA 兼容处理规范（UTS #46），包括过渡性和非过渡性处理模式、Unicode 字符映射表（IdnaMappingTable）与 NFC 归一化检查。",
      "evidence": ["lib/tr46map.c", "lib/tables.c", "lib/context.c", "lib/bidi.c"]
    },
    {
      "name": "libidn 兼容层",
      "description": "提供与旧版 libidn 库兼容的 API（idna_* 宏定义和 Idna_rc / Idna_flags 类型），使现有程序只需替换头文件即可从 IDNA2003 迁移到 IDNA2008。",
      "evidence": ["lib/idn2.h.in:329", "lib/idna.h", "lib/idna.c"]
    },
    {
      "name": "本地化编码支持",
      "description": "支持从系统本地字符编码到 UTF-8 的双向转换（依赖 libiconv/libunistring/gnulib），使应用程序能以本地编码处理国际化域名字符串。",
      "evidence": ["lib/lookup.c:662", "lib/decode.c:367", "lib/register.c:244"]
